{"op":"write","path":"/app/ars.R","content":"## Adaptive Rejection Sampling (Gilks & Wild, 1992)
## Modular R implementation for univariate, log-concave densities.

# ---------------------------------------------------------------------------
# Input validation and small helper functions
# ---------------------------------------------------------------------------

.ars_validate_input <- function(density_function, domain, n) {
  if (!is.function(density_function)) {
    stop("ars: 'density_function' must be a function")
  }
  if (!is.numeric(domain) || length(domain) != 2L || anyNA(domain)) {
    stop("ars: 'domain' must be a numeric vector of length 2 (lower, upper)")
  }
  if (domain[1] >= domain[2]) {
    stop("ars: invalid domain; lower bound must be strictly less than upper bound")
  }
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || n < 0 ||
      abs(n - round(n)) > 1e-8) {
    stop("ars: 'n' must be a non-negative integer")
  }
  invisible(TRUE)
}

.ars_log_density <- function(density_function, x) {
  vals <- tryCatch(as.numeric(density_function(x)),
                   error = function(e) {
                     stop("ars: density_function failed to evaluate: ",
                          conditionMessage(e), call. = FALSE)
                   })
  if (length(vals) != length(x)) {
    stop("ars: density_function must be vectorized and return one value per x")
  }
  if (anyNA(vals) || any(vals < 0)) {
    stop("ars: density_function returned negative or NA values")
  }
  log(vals)
}

.ars_derivative <- function(density_function, x) {
  h0 <- .ars_log_density(density_function, x)
  eps <- 1e-6 * pmax(1, abs(x))
  hp <- .ars_log_density(density_function, x + eps)
  hm <- .ars_log_density(density_function, x - eps)

  d <- rep(NA_real_, length(x))
  ok <- is.finite(hp) & is.finite(hm)
  d[ok] <- (hp[ok] - hm[ok]) / (2 * eps[ok])

  # Points near a boundary may only have a one-sided finite value.
  forward <- !ok & is.finite(hp)
  d[forward] <- (hp[forward] - h0[forward]) / eps[forward]
  backward <- !ok & is.finite(hm)
  d[backward] <- (h0[backward] - hm[backward]) / eps[backward]

  if (any(!is.finite(d))) {
    stop("ars: could not compute a finite derivative of the log-density")
  }
  d
}

# ---------------------------------------------------------------------------
# Initial abscissae
# ---------------------------------------------------------------------------

.ars_initial_candidates <- function(domain) {
  lower <- domain[1]
  upper <- domain[2]

  if (is.finite(lower) && is.finite(upper)) {
    return(lower + (upper - lower) * c(0.05, 0.15, 0.30, 0.50,
                                       0.70, 0.85, 0.95))
  }
  if (is.finite(lower)) {
    step <- if (abs(lower) > 0.1) abs(lower) * 0.1 else 0.1
    return(lower + step * c(0.1, 0.5, 1, 2, 5, 10, 20, 50))
  }
  if (is.finite(upper)) {
    step <- if (abs(upper) > 0.1) abs(upper) * 0.1 else 0.1
    return(upper - step * c(50, 20, 10, 5, 2, 1, 0.5, 0.1))
  }
  c(-2, -1, 0, 1, 2)
}

.ars_initial_abscissae <- function(density_function, domain) {
  candidates <- .ars_initial_candidates(domain)
  hc <- .ars_log_density(density_function, candidates)

  valid <- is.finite(hc) &
    candidates > domain[1] &
    candidates < domain[2]
  vx <- candidates[valid]

  if (length(vx) == 0L) {
    stop("ars: no valid starting points with positive density were found")
  }

  lower <- domain[1]
  upper <- domain[2]

  if (is.finite(lower) && is.finite(upper)) {
    idx <- unique(round(seq(1, length(vx), length.out = min(5, length(vx)))))
    xs <- vx[idx]
  } else if (is.finite(lower)) {
    xs <- vx[seq_len(min(5, length(vx)))]
  } else if (is.finite(upper)) {
    m <- length(vx)
    xs <- vx[seq(max(1, m - 4), m)]
  } else {
    xs <- vx[seq_len(min(5, length(vx)))]
  }

  if (length(xs) < 2L) {
    stop("ars: need at least two valid starting points")
  }
  sort(xs)
}

# ---------------------------------------------------------------------------
# Upper hull construction
# ---------------------------------------------------------------------------

.ars_interval_log_weight <- function(a, b, alpha, beta) {
  if (is.infinite(a) && is.infinite(b)) {
    stop("ars: cannot integrate a proposal over the whole real line")
  }

  # Left tail (-Inf, b): integrable only when beta > 0.
  if (is.infinite(a)) {
    if (beta <= 0) {
      stop("ars: proposal density is not integrable on the left tail")
    }
    return(alpha + beta * b - log(beta))
  }

  # Right tail (a, Inf): integrable only when beta < 0.
  if (is.infinite(b)) {
    if (beta >= 0) {
      stop("ars: proposal density is not integrable on the right tail")
    }
    return(alpha + beta * a - log(-beta))
  }

  if (b <= a) return(-Inf)
  if (abs(beta) < 1e-12) return(alpha + log(b - a))

  eb <- exp(beta * b)
  ea <- exp(beta * a)

  if (is.finite(eb) && is.finite(ea) && eb != ea) {
    return(alpha + log(abs(eb - ea)) - log(abs(beta)))
  }

  # Stable fallback for large |beta * x|.
  if (beta > 0) {
    return(alpha + beta * b - log(beta) +
             log1p(-exp(-beta * (b - a))))
  } else {
    return(alpha + beta * a - log(-beta) +
             log1p(-exp(beta * (b - a))))
  }
}

.ars_build_hull <- function(xs, hs, ds, domain) {
  ord <- order(xs)
  xs <- xs[ord]
  hs <- hs[ord]
  ds <- ds[ord]

  keep <- c(TRUE, diff(xs) > 1e-10)
  xs <- xs[keep]
  hs <- hs[keep]
  ds <- ds[keep]

  if (length(xs) < 2L) {
    stop("ars: at least two distinct support points are required")
  }

  # Log-concavity implies a non-increasing first derivative.
  if (any(diff(ds) > 1e-8)) {
    stop("ars: density is not log-concave (log-density derivative is not non-increasing)")
  }

  lower <- domain[1]
  upper <- domain[2]
  m <- length(xs)

  # Breakpoints: abscissae, tangent intersections, finite domain boundaries.
  bp <- xs
  if (m > 1L) {
    for (i in seq_len(m - 1L)) {
      d1 <- ds[i]
      d2 <- ds[i + 1L]
      if (abs(d1 - d2) > 1e-12) {
        c1 <- hs[i] - d1 * xs[i]
        c2 <- hs[i + 1L] - d2 * xs[i + 1L]
        xi <- (c2 - c1) / (d1 - d2)
        if (is.finite(xi) && xi > xs[i] + 1e-10 && xi < xs[i + 1L] - 1e-10) {
          bp <- c(bp, xi)
        }
      }
    }
  }
  if (is.finite(lower)) bp <- c(bp, lower)
  if (is.finite(upper)) bp <- c(bp, upper)
  bp <- sort(unique(bp))

  segments <- list()

  # Interior segments between finite breakpoints.
  for (i in seq_len(length(bp) - 1L)) {
    a <- bp[i]
    b <- bp[i + 1L]
    if (b - a < 1e-10) next
    mid <- (a + b) / 2
    tangent_at_mid <- hs + ds * (mid - xs)
    j <- which.min(tangent_at_mid)[1]
    alpha <- hs[j] - ds[j] * xs[j]
    beta <- ds[j]
    logw <- .ars_interval_log_weight(a, b, alpha, beta)
    segments[[length(segments) + 1L]] <- list(
      a = a, b = b, alpha = alpha, beta = beta, logw = logw
    )
  }

  # Left tail: the tangent at the first abscissa is the active envelope.
  if (is.infinite(lower)) {
    a <- -Inf
    b <- bp[1]
    alpha <- hs[1] - ds[1] * xs[1]
    beta <- ds[1]
    logw <- .ars_interval_log_weight(a, b, alpha, beta)
    segments[[length(segments) + 1L]] <- list(
      a = a, b = b, alpha = alpha, beta = beta, logw = logw
    )
  }

  # Right tail: the tangent at the last abscissa is the active envelope.
  if (is.infinite(upper)) {
    a <- bp[length(bp)]
    b <- Inf
    alpha <- hs[m] - ds[m] * xs[m]
    beta <- ds[m]
    logw <- .ars_interval_log_weight(a, b, alpha, beta)
    segments[[length(segments) + 1L]] <- list(
      a = a, b = b, alpha = alpha, beta = beta, logw = logw
    )
  }

  if (length(segments) == 0L) {
    stop("ars: unable to build a proposal density")
  }

  logw <- vapply(segments, function(s) s$logw, numeric(1))
  maxw <- max(logw)
  w <- exp(logw - maxw)
  tot <- sum(w)
  if (!is.finite(tot) || tot <= 0) {
    stop("ars: failed to normalize the proposal density")
  }

  list(
    segments = segments,
    prob = w / tot,
    log_total = maxw + log(tot)
  )
}

# ---------------------------------------------------------------------------
# Sampling from the piecewise-exponential proposal
# ---------------------------------------------------------------------------

.ars_inverse <- function(a, b, alpha, beta, u) {
  # alpha is not needed for the inverse CDF: the normalizing constant cancels.
  if (is.infinite(a)) {
    return(b + log(u) / beta)       # left tail, beta > 0
  }
  if (is.infinite(b)) {
    return(a + log(1 - u) / beta)   # right tail, beta < 0
  }
  if (abs(beta) < 1e-12) {
    return(a + u * (b - a))
  }

  eb <- exp(beta * b)
  ea <- exp(beta * a)
  if (is.finite(eb) && is.finite(ea) && eb != ea) {
    return(log(ea + u * (eb - ea)) / beta)
  }

  # Stable fallback for large |beta * x|.
  if (beta > 0) {
    return(b + log(u + (1 - u) * exp(-beta * (b - a))) / beta)
  } else {
    return(a + log((1 - u) + u * exp(beta * (b - a))) / beta)
  }
}

.ars_draw <- function(hull, n = 1L) {
  segments <- hull$segments
  idx <- sample.int(length(segments), size = n, replace = TRUE, prob = hull$prob)
  out <- numeric(n)
  for (i in seq_len(n)) {
    s <- segments[[idx[i]]]
    out[i] <- .ars_inverse(s$a, s$b, s$alpha, s$beta, runif(1))
  }
  out
}

# ---------------------------------------------------------------------------
# Log-concavity checks
# ---------------------------------------------------------------------------

.ars_upper_value <- function(x, xs, hs, ds) {
  min(hs + ds * (x - xs))
}

.ars_check_concavity <- function(x, dx, xs, ds, tol = 1e-6) {
  m <- length(xs)
  if (m < 2L) return(TRUE)
  k <- findInterval(x, xs)
  if (k <= 0L) return(dx >= ds[1L] - tol)
  if (k >= m) return(dx <= ds[m] + tol)
  dleft <- ds[k]
  dright <- ds[k + 1L]
  (dleft >= dx - tol) && (dx >= dright - tol)
}

# ---------------------------------------------------------------------------
# Public adaptive rejection sampler
# ---------------------------------------------------------------------------

ars <- function(density_function, domain, n = 1000) {
  .ars_validate_input(density_function, domain, n)

  if (n == 0) {
    return(numeric(0))
  }

  xs <- .ars_initial_abscissae(density_function, domain)
  hs <- .ars_log_density(density_function, xs)
  ds <- .ars_derivative(density_function, xs)

  hull <- .ars_build_hull(xs, hs, ds, domain)

  samples <- numeric(n)
  filled <- 0L
  iter <- 0L
  max_iter <- max(10000L, as.integer(n) * 100L + 1000L)
  max_support_points <- 50L

  while (filled < n && iter < max_iter) {
    iter <- iter + 1L
    cand <- .ars_draw(hull, 1L)[1L]

    hx <- .ars_log_density(density_function, cand)
    if (!is.finite(hx)) {
      # The proposal should have positive density here, so this is unusual.
      next
    }

    dx <- .ars_derivative(density_function, cand)

    # Check that the newly evaluated derivative is consistent with concavity.
    if (!.ars_check_concavity(cand, dx, xs, ds)) {
      stop("ars: density is not log-concave (derivative violates non-increasing condition)",
           call. = FALSE)
    }

    # Check that the density lies below the current upper hull.
    Ux <- .ars_upper_value(cand, xs, hs, ds)
    if (!is.finite(Ux) || hx > Ux + 1e-6) {
      stop("ars: density is not log-concave (log-density lies above the upper hull)",
           call. = FALSE)
    }

    # Accept/reject using log(exp(h-U) * Z) = h - U + log(Z).
    logZ <- hull$log_total
    logratio <- hx - Ux + logZ
    if (logratio >= 0 || log(runif(1)) <= logratio) {
      filled <- filled + 1L
      samples[filled] <- cand
    }

    # Adapt the envelope with every evaluated point (unless already known
    # or the support-point cap has been reached).
    if (length(xs) < max_support_points &&
        !any(abs(cand - xs) < 1e-8 * pmax(1, abs(xs)))) {
      allx <- c(xs, cand)
      allh <- c(hs, hx)
      alld <- c(ds, dx)
      ord <- order(allx)
      xs <- allx[ord]
      hs <- allh[ord]
      ds <- alld[ord]
      hull <- .ars_build_hull(xs, hs, ds, domain)
    }
  }

  if (filled < n) {
    stop("ars: failed to generate the requested number of samples", call. = FALSE)
  }

  samples
}

# ---------------------------------------------------------------------------
# Formal tests
# ---------------------------------------------------------------------------

.report_test <- function(name, ok, mean_value = NA_real_, sd_value = NA_real_) {
  status <- if (isTRUE(ok)) "PASS" else "FAIL"
  cat(sprintf("%s: %s (mean = %s, sd = %s)\n",
              name, status,
              ifelse(is.na(mean_value), "NA", format(mean_value, digits = 4)),
              ifelse(is.na(sd_value), "NA", format(sd_value, digits = 4))))
  invisible(ok)
}

.test_validation <- function() {
  ok <- TRUE

  expect_error <- function(expr) {
    tryCatch({
      expr
      FALSE
    }, error = function(e) TRUE)
  }

  if (!expect_error(ars(dnorm, c(-Inf, Inf), -5))) {
    cat("  - negative n was not rejected\n")
    ok <- FALSE
  }
  if (!expect_error(ars(dnorm, c(-Inf, Inf), 2.5))) {
    cat("  - fractional n was not rejected\n")
    ok <- FALSE
  }
  if (!expect_error(ars(dnorm, c(1, 0), 10))) {
    cat("  - invalid domain was not rejected\n")
    ok <- FALSE
  }
  if (!expect_error(ars("not a function", c(-Inf, Inf), 10))) {
    cat("  - non-function density was not rejected\n")
    ok <- FALSE
  }
  if (!expect_error(ars(dnorm, c(0, 1), 10))) {
    cat("  - sampling from zero density outside selected abscissae should error\n")
    # dnorm is strictly positive everywhere, so this should normally not error;
    # this branch is only a sanity check that the sampler can be invoked.
    ok <- ok
  }

  .report_test("INPUT_VALIDATION_TEST", ok)
  invisible(ok)
}

.test_normal <- function() {
  cat("  Drawing 20000 samples from N(0,1)...\n")
  set.seed(12345)
  s <- ars(dnorm, c(-Inf, Inf), 20000)
  m <- mean(s)
  sdv <- sd(s)
  ok <- abs(m) < 0.05 && abs(sdv - 1) < 0.05
  .report_test("NORMAL_TEST", ok, m, sdv)
  write.table(s, "/app/normal_samples.txt", row.names = FALSE,
              col.names = FALSE)
  invisible(ok)
}

.test_exponential <- function() {
  cat("  Drawing 20000 samples from Exp(1)...\n")
  set.seed(12346)
  s <- ars(dexp, c(0, Inf), 20000)
  m <- mean(s)
  sdv <- sd(s)
  ks_p <- tryCatch(
    suppressWarnings(ks.test(s, "pexp", 1)$p.value),
    error = function(e) NA_real_
  )
  ok <- abs(m - 1) < 0.05 && abs(sdv - 1) < 0.05 &&
    (!is.na(ks_p) && ks_p > 0.001)
  .report_test("EXPONENTIAL_TEST", ok, m, sdv)
  write.table(s, "/app/exponential_samples.txt", row.names = FALSE,
              col.names = FALSE)
  invisible(ok)
}

.test_uniform <- function() {
  cat("  Drawing 10000 samples from U(0,1)...\n")
  set.seed(12347)
  s <- ars(dunif, c(0, 1), 10000)
  m <- mean(s)
  sdv <- sd(s)
  ok <- abs(m - 0.5) < 0.03 && abs(sdv - sqrt(1 / 12)) < 0.03
  .report_test("UNIFORM_TEST", ok, m, sdv)
  invisible(ok)
}

.test_non_log_concave <- function() {
  cat("  Checking that a non-log-concave density is rejected...\n")
  caught <- tryCatch({
    ars(function(x) dcauchy(x), c(-Inf, Inf), 100)
    FALSE
  }, error = function(e) TRUE)
  .report_test("NON_LOG_CONCAVE_TEST", caught)
  invisible(caught)
}

# The public test function requested by the task.
test <- function() {
  cat("Running adaptive rejection sampler tests\n")
  cat("---\nInput validation:\n")
  .test_validation()
  cat("---\nStandard normal:\n")
  .test_normal()
  cat("---\nExponential:\n")
  .test_exponential()
  cat("---\nUniform (flat log-density):\n")
  .test_uniform()
  cat("---\nNon-log-concave detection:\n")
  .test_non_log_concave()
  cat("\nSample file written: /app/normal_samples.txt, /app/exponential_samples.txt\n")
}
