.report_test <- function(name, ok, mean_value = NA_real_, sd_value = NA_real_) {
  status <- if (isTRUE(ok)) "PASS" else "FAIL"
  cat(sprintf("%s: %s (mean = %s, sd = %s)
",
              name, status,
              ifelse(is.na(mean_value), "NA", format(mean_value, digits = 4)),
              ifelse(is.na(sd_value), "NA", format(sd_value, digits = 4))))
  invisible(ok)
}

.test_validation <- function() {
  ok <- TRUE

  expect_error <- function(expr) {
    tryCatch({
      expr
      FALSE
    }, error = function(e) TRUE)
  }

  if (!expect_error(ars(dnorm, c(-Inf, Inf), -5))) {
    cat("  - negative n was not rejected
")
    ok <- FALSE
  }
  if (!expect_error(ars(dnorm, c(-Inf, Inf), 2.5))) {
    cat("  - fractional n was not rejected
")
    ok <- FALSE
  }
  if (!expect_error(ars(dnorm, c(1, 0), 10))) {
    cat("  - invalid domain was not rejected
")
    ok <- FALSE
  }
  if (!expect_error(ars("not a function", c(-Inf, Inf), 10))) {
    cat("  - non-function density was not rejected
")
    ok <- FALSE
  }
  if (!expect_error(ars(dnorm, c(0, 1), 10))) {
    cat("  - sampling from zero density outside selected abscissae should error
