.report_test <- function(name, ok, mean_value = NA_real_, sd_value = NA_real_) {
  status <- if (isTRUE(ok)) "PASS" else "FAIL"
  cat(sprintf("%s: %s (mean = %s, sd = %s)\n",
              name, status,
              ifelse(is.na(mean_value), "NA", format(mean_value, digits = 4)),
              ifelse(is.na(sd_value), "NA", format(sd_value, digits = 4))))
  invisible(ok)
}

.test_validation <- function() {
  ok <- TRUE

  expect_error <- function(expr) {
    tryCatch({
      expr
      FALSE
    }, error = function(e) TRUE)
  }

  checks <- list(
    "negative n"      = quote(ars(dnorm, c(-Inf, Inf), -5)),
    "fractional n"    = quote(ars(dnorm, c(-Inf, Inf), 2.5)),
    "infinite n"      = quote(ars(dnorm, c(-Inf, Inf), Inf)),
    "non-numeric n"   = quote(ars(dnorm, c(-Inf, Inf), "10")),
    "reversed domain" = quote(ars(dnorm, c(1, 0), 10)),
    "NA domain"       = quote(ars(dnorm, c(NA, 1), 10)),
    "non-function"    = quote(ars("not a function", c(-Inf, Inf), 10))
  )

  for (nm in names(checks)) {
    if (!expect_error(eval(checks[[nm]]))) {
      cat(sprintf("  - invalid case not rejected: %s\n", nm))
      ok <- FALSE
    }
  }

  .report_test("INPUT_VALIDATION_TEST", ok)
  invisible(ok)
}

.test_normal <- function() {
  cat("  Drawing 20000 samples from N(0,1)...\n")
  set.seed(12345)
  s <- ars(dnorm, c(-Inf, Inf), 20000)
  m <- mean(s)
  sdv <- sd(s)
  ok <- abs(m) < 0.05 && abs(sdv - 1) < 0.05
  .report_test("NORMAL_TEST", ok, m, sdv)
  write.table(s, "/app/normal_samples.txt", row.names = FALSE,
              col.names = FALSE)
  invisible(ok)
}

.test_exponential <- function() {
  cat("  Drawing 20000 samples from Exp(1)...\n")
  set.seed(12346)
  s <- ars(dexp, c(0, Inf), 20000)
  m <- mean(s)
  sdv <- sd(s)
  ks_p <- tryCatch(
    suppressWarnings(ks.test(s, "pexp", 1)$p.value),
    error = function(e) NA_real_
  )
  ok <- abs(m - 1) < 0.05 && abs(sdv - 1) < 0.05 &&
    (!is.na(ks_p) && ks_p > 0.001)
  .report_test("EXPONENTIAL_TEST", ok, m, sdv)
  write.table(s, "/app/exponential_samples.txt", row.names = FALSE,
              col.names = FALSE)
  invisible(ok)
}

.test_uniform <- function() {
  cat("  Drawing 10000 samples from U(0,1)...\n")
  set.seed(12347)
  s <- ars(dunif, c(0, 1), 10000)
  m <- mean(s)
  sdv <- sd(s)
  ok <- abs(m - 0.5) < 0.03 && abs(sdv - sqrt(1 / 12)) < 0.03
  .report_test("UNIFORM_TEST", ok, m, sdv)
  invisible(ok)
}

.test_non_log_concave <- function() {
  cat("  Checking that a non-log-concave density is rejected...\n")
  caught <- tryCatch({
    ars(function(x) dcauchy(x), c(-Inf, Inf), 100)
    FALSE
  }, error = function(e) TRUE)
  .report_test("NON_LOG_CONCAVE_TEST", caught)
  invisible(caught)
}

