.ars_build_hull <- function(xs, hs, ds, domain) {
  ord <- order(xs)
  xs <- xs[ord]
  hs <- hs[ord]
  ds <- ds[ord]

  keep <- c(TRUE, diff(xs) > 1e-10)
  xs <- xs[keep]
  hs <- hs[keep]
  ds <- ds[keep]

  if (length(xs) < 2L) {
    stop("ars: at least two distinct support points are required")
  }

  # Log-concavity implies a non-increasing first derivative.
  if (any(diff(ds) > 1e-8)) {
    stop("ars: density is not log-concave (log-density derivative is not non-increasing)"
    )
  }

  lower <- domain[1]
  upper <- domain[2]
  m <- length(xs)

  # Breakpoints: abscissae, tangent intersections, finite domain boundaries.
  bp <- xs
  if (m > 1L) {
    for (i in seq_len(m - 1L)) {
      d1 <- ds[i]
      d2 <- ds[i + 1L]
      if (abs(d1 - d2) > 1e-12) {
        c1 <- hs[i] - d1 * xs[i]
        c2 <- hs[i + 1L] - d2 * xs[i + 1L]
        xi <- (c2 - c1) / (d1 - d2)
        if (is.finite(xi) && xi > xs[i] + 1e-10 && xi < xs[i + 1L] - 1e-10) {
          bp <- c(bp, xi)
        }
      }
    }
  }
  if (is.finite(lower)) bp <- c(bp, lower)
  if (is.finite(upper)) bp <- c(bp, upper)
  bp <- sort(unique(bp))

  segments <- list()

  # Interior segments between finite breakpoints.
  for (i in seq_len(length(bp) - 1L)) {
    a <- bp[i]
    b <- bp[i + 1L]
    if (b - a < 1e-10) next
    mid <- (a + b) / 2
    tangent_at_mid <- hs + ds * (mid - xs)
    j <- which.min(tangent_at_mid)[1]
    alpha <- hs[j] - ds[j] * xs[j]
    beta <- ds[j]
    logw <- .ars_interval_log_weight(a, b, alpha, beta)
    segments[[length(segments) + 1L]] <- list(
      a = a, b = b, alpha = alpha, beta = beta, logw = logw
    )
  }

  # Left tail: the tangent at the first abscissa is the active envelope.
  if (is.infinite(lower)) {
    a <- -Inf
    b <- bp[1]
    alpha <- hs[1] - ds[1] * xs[1]
    beta <- ds[1]
    logw <- .ars_interval_log_weight(a, b, alpha, beta)
    segments[[length(segments) + 1L]] <- list(
      a = a, b = b, alpha = alpha, beta = beta, logw = logw
    )
  }

  # Right tail: the tangent at the last abscissa is the active envelope.
  if (is.infinite(upper)) {
    a <- bp[length(bp)]
    b <- Inf
    alpha <- hs[m] - ds[m] * xs[m]
    beta <- ds[m]
    logw <- .ars_interval_log_weight(a, b, alpha, beta)
    segments[[length(segments) + 1L]] <- list(
      a = a, b = b, alpha = alpha, beta = beta, logw = logw
    )
  }

  if (length(segments) == 0L) {
    stop("ars: unable to build a proposal density")
  }

  logw <- vapply(segments, function(s) s$logw, numeric(1))
  maxw <- max(logw)
  w <- exp(logw - maxw)
  tot <- sum(w)
  if (!is.finite(tot) || tot <= 0) {
    stop("ars: failed to normalize the proposal density")
  }

  list(
    segments = segments,
    prob = w / tot,
    log_total = maxw + log(tot)
  )
}

