dbg_build_hull <- function(xs, hs, ds, domain) {
  ord <- order(xs); xs <- xs[ord]; hs <- hs[ord]; ds <- ds[ord]
  keep <- c(TRUE, diff(xs) > 1e-10)
  xs <- xs[keep]; hs <- hs[keep]; ds <- ds[keep]
  if (length(xs) < 2L) stop("need >=2")
  if (any(diff(ds) > 1e-8)) stop("not log-concave (deriv not non-increasing)")
  lower <- domain[1]; upper <- domain[2]; m <- length(xs)
  bp <- xs
  for (i in seq_len(m - 1L)) {
    d1 <- ds[i]; d2 <- ds[i + 1L]
    if (abs(d1 - d2) > 1e-12) {
      c1 <- hs[i] - d1 * xs[i]; c2 <- hs[i + 1L] - d2 * xs[i + 1L]
      xi <- (c2 - c1) / (d1 - d2)
      if (is.finite(xi) && xi > xs[i] + 1e-10 && xi < xs[i + 1L] - 1e-10) bp <- c(bp, xi)
    }
  }
  if (is.finite(lower)) bp <- c(bp, lower)
  if (is.finite(upper)) bp <- c(bp, upper)
  bp <- sort(unique(bp))
  cat("DEBUG bp len:", length(bp), "\n")
  cat("DEBUG bp:", bp, "\n")
  segments <- list()
  for (i in seq_len(length(bp) - 1L)) {
    a <- bp[i]; b <- bp[i + 1L]
    if (b - a < 1e-10) next
    mid <- (a + b) / 2
    tangent_at_mid <- hs + ds * (mid - xs)
